:root{--nv:#0f1b2b;--nv2:#18283d;--rd:#c8102e;--rd2:#a50d26;--bg:#fff;--gr:#f3f4f6;--ink:#17202c;--mut:#5b6573;--ln:#e1e4e9;color-scheme:light}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 "Helvetica Neue",Arial,sans-serif}
h1,h2,h3{font-family:"Arial Narrow","Helvetica Neue",Arial,sans-serif;font-weight:800;line-height:1.06;letter-spacing:-.015em;margin:0}h2{font-size:clamp(1.9rem,3.8vw,2.9rem)}a{color:inherit;text-decoration:none}p{margin:0}
:focus-visible{outline:3px solid #f2a900;outline-offset:3px}
.w{max-width:1200px;margin:0 auto;padding:0 24px}section{padding:88px 0}.gr{background:var(--gr)}.dk{background:var(--nv);color:#fff}.dk p{color:#b8c2d0}
.eb{font:800 .72rem Arial;letter-spacing:.18em;text-transform:uppercase;color:var(--rd);margin-bottom:14px}.dk .eb,.hero .eb{color:#ff6b80}
.hd{max-width:720px;margin-bottom:44px}.hd p{color:var(--mut);margin-top:14px}
.btn{display:inline-block;padding:15px 28px;font:800 .8rem Arial;letter-spacing:.08em;text-transform:uppercase;background:var(--rd);color:#fff;border:2px solid var(--rd);border-radius:4px;cursor:pointer;transition:.2s}.btn:hover{background:var(--rd2);border-color:var(--rd2);transform:translateY(-2px)}
.btn.o{background:transparent;border-color:#fff}.btn.o:hover{background:#fff;color:var(--nv)}.btn.k{background:var(--nv);border-color:var(--nv)}.btn.k:hover{background:var(--rd);border-color:var(--rd)}.btn.ol{background:transparent;color:var(--nv);border-color:var(--nv)}.btn.ol:hover{background:var(--nv);color:#fff}
.lnk{font:800 .76rem Arial;letter-spacing:.1em;text-transform:uppercase;color:var(--rd)}
header{position:sticky;top:0;z-index:60;background:#fff;box-shadow:0 1px 0 var(--ln)}.bar{background:var(--nv);color:#cdd5e0;font-size:.78rem}.bar .w{display:flex;justify-content:space-between;padding-top:7px;padding-bottom:7px}
.nav{display:flex;align-items:center;justify-content:space-between;height:78px;gap:18px}
.logo{display:flex;align-items:center;gap:10px;font:800 1.3rem/1 "Arial Narrow",Arial,sans-serif;color:var(--nv)}.logo small{display:block;font:700 .56rem Arial;letter-spacing:.22em;text-transform:uppercase;color:var(--rd);margin-top:3px}
.lg{width:34px;height:34px;background:var(--rd);border-radius:50% 50% 50% 8px;position:relative;flex:none}.lg:after{content:"";position:absolute;left:9px;top:8px;width:16px;height:10px;border:3px solid #fff;border-bottom:0;transform:skewX(0)}
nav>ul{display:flex;gap:26px;list-style:none;margin:0;padding:0;font:700 .84rem Arial}nav a:hover{color:var(--rd)}li.dd{position:relative}
.sub{display:none;position:absolute;left:-14px;top:100%;min-width:250px;background:#fff;box-shadow:0 14px 34px rgba(0,0,0,.16);padding:10px 0;list-style:none;margin:0;border-top:3px solid var(--rd)}.dd:hover .sub,.dd:focus-within .sub{display:block}.sub a{display:block;padding:9px 20px;font-weight:600}.sub a:hover{background:var(--gr)}
.nr{display:flex;align-items:center;gap:16px}.tel{font:800 1rem Arial;color:var(--nv)}.nr .btn{padding:12px 18px;font-size:.74rem}
#bg{display:none;background:none;border:0;font-size:1.7rem;cursor:pointer;color:var(--nv)}
.hero{position:relative;min-height:88vh;display:flex;align-items:center;color:#fff;background:linear-gradient(90deg,rgba(10,18,30,.92),rgba(10,18,30,.6) 60%,rgba(10,18,30,.25)),url('data:image/jpeg;base64,') center/cover;padding:90px 0}
.hero h1{font-size:clamp(2.5rem,6vw,4.9rem);max-width:780px}.hero p.l{max-width:560px;margin:22px 0 30px;color:#dbe2ec;font-size:1.1rem}.cta{display:flex;gap:12px;flex-wrap:wrap}
.tag{position:absolute;right:24px;bottom:22px;font:700 .66rem Arial;letter-spacing:.12em;text-transform:uppercase;color:#8d9bb0;border:1px dashed #51627a;padding:7px 12px}
.ts{display:flex;flex-wrap:wrap;gap:10px 28px;margin-top:34px;font-size:.88rem;color:#cdd6e2}.ts span:before{content:"✓ ";color:#ff6b80;font-weight:900}
.rate{margin-top:20px;font-size:.88rem;color:#cdd6e2}.rate b{color:#fff}.st{color:#f5b301;letter-spacing:2px}
.tb{background:var(--nv2);color:#fff}.tb .w{display:grid;grid-template-columns:repeat(4,1fr)}.tb div.i{padding:24px 22px;border-right:1px solid rgba(255,255,255,.1)}.tb div.i:last-child{border:0}.tb b{display:block;font:800 1.5rem "Arial Narrow",Arial;color:#fff}.tb small{color:#aab6c6}
.two{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}.two p{color:var(--mut);margin-top:16px}.chk{list-style:none;margin:22px 0 28px;padding:0}.chk li{padding:7px 0 7px 28px;position:relative;color:var(--ink)}.chk li:before{content:"✓";position:absolute;left:0;color:var(--rd);font-weight:900}
.ph{position:relative;overflow:hidden;background:linear-gradient(145deg,#d9dee6,#eceff3);border:1px dashed #a7b0be;display:grid;place-items:center;text-align:center;padding:18px;color:#6b7686;font:700 .68rem Arial;letter-spacing:.1em;text-transform:uppercase;aspect-ratio:4/3}.ph:before{content:"⌂";display:block;font-size:2.2rem;opacity:.4;font-weight:400}.ph img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.grp{margin-bottom:46px}.grp h3{font-size:1.5rem;margin-bottom:18px;display:flex;align-items:center;gap:14px}.grp h3:after{content:"";flex:1;border-top:1px solid var(--ln)}
.sg{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.sc{background:#fff;border:1px solid var(--ln);transition:.25s;display:flex;flex-direction:column}.sc:hover{transform:translateY(-5px);box-shadow:0 16px 34px rgba(15,27,43,.14);border-color:var(--rd)}.sc.f{grid-column:span 2}.sc .ph{aspect-ratio:16/9;border:0;border-bottom:1px dashed #a7b0be}.sc .in{padding:18px 20px 22px;flex:1;display:flex;flex-direction:column}.sc h4{font:800 1.1rem "Arial Narrow",Arial;margin:0 0 6px}.sc p{font-size:.88rem;color:var(--mut);flex:1;margin-bottom:12px}
.rc{display:grid;grid-template-columns:1fr 1fr}.rc>div{position:relative;min-height:520px;padding:56px;display:flex;flex-direction:column;justify-content:flex-end;color:#fff;background:linear-gradient(0deg,rgba(10,18,30,.92),rgba(10,18,30,.35)),url('data:image/jpeg;base64,') center/cover}.rc>div+div{background:linear-gradient(0deg,rgba(10,18,30,.92),rgba(10,18,30,.35)),url('data:image/jpeg;base64,') center/cover}.rc h2{font-size:clamp(1.8rem,3vw,2.5rem);margin-bottom:12px}.rc p{color:#d5dce7;max-width:440px;margin-bottom:24px}
.fl{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:30px}.fl button{background:#fff;border:1px solid #c3c9d3;padding:9px 18px;font:700 .78rem Arial;letter-spacing:.05em;text-transform:uppercase;cursor:pointer}.fl button.on,.fl button:hover{background:var(--nv);color:#fff;border-color:var(--nv)}
.pg{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;grid-auto-rows:240px}.pj{position:relative;overflow:hidden;background:#e6e9ee}.pj:nth-child(1),.pj:nth-child(6){grid-column:span 2;grid-row:span 2}.pj .ph{position:absolute;inset:0;aspect-ratio:auto;border:0}.pj span{position:absolute;left:14px;bottom:14px;z-index:2;background:var(--nv);color:#fff;font:700 .68rem Arial;letter-spacing:.1em;text-transform:uppercase;padding:6px 12px}
.fg4{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.fg4 div{background:var(--nv2);padding:30px;border-top:3px solid var(--rd)}.fg4 b{display:grid;place-items:center;width:42px;height:42px;background:var(--rd);font:900 .9rem Arial;margin-bottom:18px}.fg4 h3{font-size:1.25rem;margin-bottom:10px}
.pc{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;position:relative;margin-top:10px}.pc:before{content:"";position:absolute;top:24px;left:6%;right:6%;border-top:2px dashed #c3c9d3}.pc .s{position:relative}.pc b{position:relative;display:grid;place-items:center;width:50px;height:50px;border-radius:50%;background:var(--rd);color:#fff;font:900 .95rem Arial;margin-bottom:20px;border:5px solid #fff}.pc h3{font-size:1.3rem;margin-bottom:8px}.pc p{color:var(--mut);max-width:330px}
.rv4{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.q{background:#fff;border:1px solid var(--ln);padding:30px}.q p{font:600 1.2rem/1.4 Georgia,serif;margin:10px 0 18px;color:var(--ink)}.q small{font:800 .74rem Arial;letter-spacing:.1em;text-transform:uppercase;color:var(--mut)}
.wx{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:-60px;position:relative;padding:0 24px;max-width:1200px;margin-left:auto;margin-right:auto}.wx div{background:#fff;padding:28px;box-shadow:0 14px 34px rgba(15,27,43,.12);border-top:3px solid var(--rd)}.wx h3{font-size:1.2rem;margin-bottom:8px}.wx p{font-size:.92rem;color:var(--mut)}
.wimg{height:420px}.wimg .ph{height:100%;aspect-ratio:auto;border:0}
.ar{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.ar a{background:#fff;border:1px solid var(--ln);padding:18px 22px;font-weight:800;display:flex;justify-content:space-between;transition:.2s}.ar a:hover{background:var(--nv);color:#fff}.ar span{color:var(--rd)}
.bl{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.bl a{display:block;background:#fff;border:1px solid var(--ln);transition:.25s}.bl a:hover{transform:translateY(-5px);box-shadow:0 16px 34px rgba(15,27,43,.12)}.bl .in{padding:20px 22px 24px}.bl small{color:var(--mut);font-weight:700;font-size:.74rem;letter-spacing:.08em;text-transform:uppercase}.bl h3{font-size:1.2rem;margin:8px 0 14px;line-height:1.2}
.fq{max-width:860px}.fq details{border-bottom:1px solid var(--ln)}.fq summary{list-style:none;cursor:pointer;padding:22px 40px 22px 0;font:800 1.15rem "Arial Narrow",Arial;position:relative}.fq summary::-webkit-details-marker{display:none}.fq summary:after{content:"+";position:absolute;right:6px;top:18px;font-size:1.6rem;color:var(--rd);transition:.2s}.fq details[open] summary:after{content:"–"}.fq p{padding:0 0 22px;color:var(--mut)}
.cb{background:linear-gradient(90deg,rgba(10,18,30,.94),rgba(10,18,30,.7)),url('data:image/jpeg;base64,') center/cover;color:#fff;text-align:center;padding:96px 0}.cb h2{color:#fff;max-width:760px;margin:0 auto 16px}.cb p{max-width:620px;margin:0 auto 30px;color:#cfd8e4}.cb .cta{justify-content:center}
.cg{display:grid;grid-template-columns:.85fr 1.15fr;gap:60px}.cg p{color:var(--mut);margin-top:14px}.ci{margin-top:26px;font-size:.95rem}.ci b{display:block;font:800 .72rem Arial;letter-spacing:.14em;text-transform:uppercase;color:var(--rd);margin-top:16px}
form{display:grid;grid-template-columns:1fr 1fr;gap:16px;background:#fff;padding:34px;border-top:4px solid var(--rd);box-shadow:0 20px 50px rgba(15,27,43,.1)}.f{grid-column:1/-1}label{display:block;font:700 .76rem Arial;letter-spacing:.06em;text-transform:uppercase;margin-bottom:6px}input,select,textarea{width:100%;padding:14px;border:1.5px solid #c3c9d3;font:inherit;background:#fff;color:var(--ink)}input:focus,select:focus,textarea:focus{border-color:var(--rd);outline:0}textarea{height:110px}.er{color:#c0152f;font-size:.78rem;min-height:1.1em;display:block}.ok{display:none;grid-column:1/-1;background:var(--nv);color:#fff;padding:18px;font-weight:700}.note{grid-column:1/-1;font-size:.78rem;color:var(--mut)}
footer{background:#0a121e;color:#98a4b5;padding:62px 0 26px;font-size:.88rem}.fgd{display:grid;grid-template-columns:1.4fr 1.2fr 1fr 1fr;gap:34px}footer h4{color:#fff;font-size:.72rem;letter-spacing:.16em;margin:0 0 12px}footer a{display:block;margin:6px 0}footer a:hover{color:#fff}.fine{border-top:1px solid #1d2a3c;margin-top:36px;padding-top:18px;font-size:.78rem}
.rv{opacity:0;transform:translateY(24px);transition:opacity .8s,transform .8s}.rv.in{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.rv{opacity:1;transform:none;transition:none}}
@media(max-width:1000px){nav{position:absolute;left:0;right:0;top:100%;background:#fff;max-height:0;overflow:hidden;transition:max-height .35s;box-shadow:0 14px 24px rgba(0,0,0,.12)}nav.o{max-height:640px;overflow:auto}nav>ul{flex-direction:column;gap:0;padding:6px 24px 16px}nav>ul>li>a{display:block;padding:13px 0;border-bottom:1px solid var(--ln)}.sub{display:block;position:static;box-shadow:none;border:0;padding:0 0 0 14px}#bg{display:block}.hm,.bar{display:none}section{padding:60px 0}.two,.cg,.rc{grid-template-columns:1fr}.two{gap:34px}.sg,.fg4,.pg{grid-template-columns:1fr 1fr}.sc.f{grid-column:1/-1}.tb .w{grid-template-columns:1fr 1fr}.rv4,.bl,.wx,.ar,.pc{grid-template-columns:1fr}.pc:before{display:none}.wx{margin-top:0;padding-top:24px}.pg{grid-auto-rows:200px}.pj:nth-child(1),.pj:nth-child(6){grid-column:span 2;grid-row:auto}.fgd{grid-template-columns:1fr 1fr}.rc>div{min-height:380px;padding:36px 24px}}
@media(max-width:600px){.sg,.fg4,.pg,form,.fgd{grid-template-columns:1fr}.pj:nth-child(1),.pj:nth-child(6){grid-column:auto}.cta .btn{width:100%;text-align:center}.hero{padding:70px 0}.tel{font-size:.9rem}}

.hero .w{width:100%}.w.nav{max-width:1320px}nav a,.nr .btn,.logo{white-space:nowrap}nav>ul{gap:20px;font-size:.8rem}.bar a{font:800 .92rem Arial;color:#fff}.mc{display:none}
@media(max-width:1000px){.mc{display:inline-block;padding:10px 16px!important;font-size:.72rem!important}}
.hero .w,.bar .w{max-width:1320px}

@media(min-width:1001px){.pg{grid-template-columns:1.4fr 1fr;grid-auto-rows:290px}.pj:nth-child(n){grid-column:auto;grid-row:auto}.pj:nth-child(1){grid-row:span 2}}
.cityimg{height:300px;margin-bottom:26px;overflow:hidden}.cityimg img{width:100%;height:100%;object-fit:cover;object-position:50% 50%;display:block}
.pj .ph img{transition:transform .6s}.pj:hover .ph img{transform:scale(1.05)}
.cityimg img{object-position:50% 78%}
